import {uid,starterRoutines,demoRecords,demoProfile,foods,baseMeals} from './data.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>structuredClone(v),dateKey=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const state={demo:false,route:'today',user:null,profile:null,records:[],draft:null,stats:{streak:0,total:0,days:[],today:false},friends:[],photos:[],sync:'Salvo',dirty:false,ai:null};
const navs=[['today','◈','Hoje'],['workouts','▥','Treinos'],['food','◷','Alimentação'],['progress','↗','Evolução'],['friends','♧','Amigos'],['ai','✦','Auxiliar']];
const items=k=>state.records.filter(r=>r.kind===k);
let saveTimer,toastTimer,savePromise=null;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',5000)}
async function api(path,method='GET',body){let r;try{r=await fetch('/api/'+path,{method,headers:body instanceof Blob?{'Content-Type':body.type}:body?{'Content-Type':'application/json'}:{},body:body===undefined?undefined:body instanceof Blob?body:JSON.stringify(body),credentials:'same-origin'})}catch{throw new Error('Sem conexão. Seu treino continua no rascunho deste aparelho.')}let v;try{v=await r.json()}catch{throw new Error('Resposta inesperada do servidor.')}if(!r.ok){const e=new Error(v.error||'Não foi possível concluir.');e.status=r.status;throw e}return v}
function demoPersist(){localStorage.setItem('forma-demo',JSON.stringify({profile:state.profile,records:state.records,draft:state.draft}));demoStats()}
function demoStats(){const days=[...new Set(items('workout').filter(r=>qualifies(r.data)).map(r=>dateKey(new Date(r.data.finished_at))))];const today=dateKey();let d=new Date(today+'T12:00:00-03:00'),streak=0;if(!days.includes(today))d.setDate(d.getDate()-1);while(days.includes(dateKey(d))){streak++;d.setDate(d.getDate()-1)}state.stats={days,total:days.length,streak,today:days.includes(today)}}
function qualifies(d){return new Set(d.exercises.filter(e=>e.sets.length&&e.sets.every(s=>s.done&&s.reps>0)).map(e=>e.id)).size>=3}
function completed(d){return d?.exercises?.filter(e=>e.sets.length&&e.sets.every(s=>s.done&&s.reps>0)).length||0}
async function put(kind,data,id=uid(),version){const old=state.records.find(r=>r.id===id);let row;if(state.demo){row={id,kind,data:clone(data),version:(old?.version||0)+1};if(kind==='workout')row.data.finished_at=old?.data.finished_at||new Date().toISOString()}else row=await api('records','POST',{id,kind,data,version:version??old?.version});state.records=state.records.filter(r=>r.id!==id).concat(row);if(state.demo)demoPersist();return row}
async function remove(id){if(!state.demo)await api('records/'+id,'DELETE');state.records=state.records.filter(r=>r.id!==id);if(state.demo)demoPersist()}
function cacheDraft(){if(state.draft&&!state.demo)localStorage.setItem('forma-draft-'+state.user.id,JSON.stringify({draft:state.draft,dirty:state.dirty}));if(state.demo)demoPersist()}
function changed(){state.dirty=true;state.sync=state.demo?'Salvo na demonstração':'Rascunho salvo neste aparelho';cacheDraft();syncLabel();clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft().catch(e=>{state.sync=e.message;syncLabel()}),800)}
async function saveDraft(){if(!state.draft||!state.dirty)return;if(savePromise){await savePromise;if(state.dirty)return saveDraft();return}const snapshot=clone(state.draft),snapshotText=JSON.stringify(state.draft.data);state.sync=state.demo?'Salvo na demonstração':'Sincronizando…';syncLabel();savePromise=(async()=>{try{const row=await put('draft',snapshot.data,snapshot.id,snapshot.version);if(state.draft?.id===snapshot.id){state.draft.version=row.version;state.dirty=JSON.stringify(state.draft.data)!==snapshotText;state.sync=state.dirty?'Alterações pendentes':state.demo?'Salvo na demonstração':'Salvo na nuvem';cacheDraft();syncLabel()}}catch(e){state.sync=e.status===409?'Conflito: recarregue e escolha a versão do treino.':'Pendente: '+e.message;syncLabel();throw e}finally{savePromise=null}})();await savePromise}
function syncLabel(){for(const el of document.querySelectorAll('[data-sync]'))el.textContent=state.sync}
async function load(){const s=await api('session');state.user=s.user;state.profile=s.profile;if(!state.profile)throw new Error('Perfil não encontrado. Confira a instalação do banco.');const [records,stats,friends]=await Promise.all([api('records'),api('stats'),api('friends')]);state.records=records;state.stats=stats;state.friends=friends;state.draft=items('draft')[0]||null;const cached=JSON.parse(localStorage.getItem('forma-draft-'+state.user.id)||'null');if(cached?.dirty){if(!state.draft||cached.draft.version===state.draft.version){state.draft=cached.draft;state.dirty=true;state.sync='Rascunho local pendente';}else{state.sync='Usando versão atual da nuvem';toast('O treino mudou em outro dispositivo. A versão da nuvem foi carregada. O rascunho local pode ser recuperado no treino.');}}else{state.sync='Salvo na nuvem';state.dirty=false}render()}
function enterDemo(){state.demo=true;const saved=JSON.parse(localStorage.getItem('forma-demo')||'null');state.user={id:'demo',email:'demo@exemplo.local'};state.profile=saved?.profile||clone(demoProfile);state.records=saved?.records||demoRecords();state.draft=saved?.draft||null;state.friends=[];demoStats();render()}
const button=(label,action,classes='',attrs='')=>`<button type="button" class="${classes}" data-action="${action}" ${attrs}>${label}</button>`;
function openModal(title,content){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button('✕','close','ghost','aria-label="Fechar"')}</div>${content}`;if(!modal.open)modal.showModal();modal.querySelector('input,textarea,select,button')?.focus()}
function formModal(title,html,handler,submit='Salvar'){openModal(title,`<form id="modal-form" class="form">${html}<p class="error" data-error></p><div class="actions"><button type="submit" class="primary">${submit}</button>${button('Cancelar','close','ghost')}</div></form>`);modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;f.querySelector('[data-error]').textContent='';try{await handler(Object.fromEntries(new FormData(f)),f);modal.close();render()}catch(err){f.querySelector('[data-error]').textContent=err.message}finally{b.disabled=false}}}
const field=(name,label,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const area=(name,label,value='')=>`<label>${esc(label)}<textarea name="${name}">${esc(value)}</textarea></label>`;
function auth(mode='login',message=''){state.user=null;app.innerHTML=`<div class="auth"><section class="auth-art"><div class="brand"><img src="/icon.svg" alt="">forma</div><h1>Seu ritmo.<br>Sua força.<br><span class="accent">Sua evolução.</span></h1><p>Treino, alimentação e progresso. Um espaço para cuidar da sua rotina, uma série de cada vez.</p><div class="chips"><span class="chip">Treino ABC</span><span class="chip">Alimentação possível</span><span class="chip">Progresso com amigos</span></div></section><section class="auth-main"><div class="brand"><img src="/icon.svg" alt="">forma</div><h2>${mode==='signup'?'Crie seu espaço':mode==='recover'?'Recupere sua conta':'Bom ter você aqui'}</h2><p class="muted">${mode==='login'?'Entre para continuar de onde parou.':'Seus dados de saúde ficam privados.'}</p><div class="tabs">${button('Entrar','auth-login',mode==='login'?'active':'')}${button('Criar conta','auth-signup',mode==='signup'?'active':'')}</div><form id="auth-form" class="form">${mode==='signup'?field('name','Seu nome','','text','required maxlength="80"')+field('username','Nome de usuário','','text','required pattern="[a-z0-9_]{3,24}" placeholder="ex.: walyson_caio" autocomplete="username"'):''}${field('email','E-mail','','email','required autocomplete="email"')}${mode!=='recover'?field('password','Senha','','password',`required ${mode==='signup'?'minlength="10"':''} autocomplete="${mode==='signup'?'new-password':'current-password'}"`):''}<p class="error" data-error>${esc(message)}</p><button class="primary" type="submit">${mode==='signup'?'Criar conta':mode==='recover'?'Enviar link':'Entrar'}</button></form><div class="actions" style="margin-top:16px">${button('Esqueci minha senha','auth-recover','ghost')}${button('Explorar demonstração','demo','ghost')}</div><p class="subtle">A demonstração usa dados locais e não cria uma conta.</p></section></div>`;app.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{const v=Object.fromEntries(new FormData(f));if(mode==='recover'){await api('recover','POST',v);auth('login','Se esse e-mail estiver cadastrado, você receberá um link.')}else{const r=await api(mode==='signup'?'signup':'login','POST',v);if(r.confirmation)auth('login','Conta criada. Confirme seu e-mail antes de entrar.');else{state.demo=false;await load()}}}catch(err){f.querySelector('[data-error]').textContent=err.message}finally{b.disabled=false}}}
function render(){if(!state.user){auth();return}const p=state.profile;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/icon.svg" alt="">forma</div><nav class="nav" aria-label="Principal">${navs.map(([r,s,l])=>button(`<span class="symbol">${s}</span>${l}`,'nav',state.route===r?'active':'',`data-route="${r}"`)).join('')}</nav><div class="side-bottom"><span class="pill">${state.stats.streak} dias de ofensiva</span><div class="userline"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(p.name)}</strong><br><small>@${esc(p.username)}</small></div></div>${button('Meu perfil','profile','ghost')}${button('Sair','logout','ghost')}</div></aside><main class="main"><header class="topbar"><div class="brand mobile-brand"><img src="/icon.svg" alt="">forma</div><div class="greeting"><p>Olá, <strong>${esc(p.name.split(' ')[0])}</strong></p><small>${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</small></div><div class="top-actions"><span class="pill">♨ ${state.stats.streak} dias</span>${button('Perfil','profile','ghost')}</div></header>${state.demo?'<div class="demo-banner">Demonstração • dados salvos apenas neste navegador. Login, amizades, fotos e Gemini precisam da configuração dos serviços.</div>':''}<div id="view">${views[state.route]()}</div></main></div>`;bindView();updateTimes()}
function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="actions">${actions}</div></div>`}
function week(){const now=new Date(),day=(now.getDay()+6)%7;now.setDate(now.getDate()-day);return `<div class="week">${['S','T','Q','Q','S','S','D'].map((l,i)=>{const d=new Date(now);d.setDate(d.getDate()+i);const k=dateKey(d);return `<div class="day ${state.stats.days.includes(k)?'done':''} ${k===dateKey()?'today':''}">${l}<strong>${state.stats.days.includes(k)?'✓':d.getDate()}</strong></div>`}).join('')}</div>`}
function today(){const routines=items('routine'),index=(new Date().getDay()+6)%7,r=routines.find(r=>r.data.group===['A','B','C','A','B','C',''][index])||routines[0];return head('Um passo mais forte.','Sua rotina de hoje, sem complicação.')+`<div class="grid two"><section class="panel focus"><span class="eyebrow">${state.draft?'Treino em andamento':index===6?'Domingo • recuperação':'Sua próxima sessão'}</span><span class="huge">${esc(state.draft?.data.group||r?.data.group||'F')}</span><h2>${esc(state.draft?.data.name||r?.data.name||'Monte seu primeiro treino')}</h2><p class="muted">${state.draft?`${completed(state.draft.data)} exercícios concluídos. Retome do ponto em que parou.`:index===6?'Descanso também faz parte da evolução. Treine conforme seu planejamento e recuperação.':r?`${r.data.exercises.length} exercícios · cargas e repetições no seu ritmo.`:'Cadastre uma ficha ou peça uma proposta ao auxiliar.'}</p>${button(state.draft?'Continuar treino':r?'Iniciar treino':'Criar treino',state.draft?'continue':r?'start':'new-routine','primary',r?`data-id="${r.id}"`:'')}</section><section class="panel"><span class="eyebrow">Sua constância</span><div class="metric">${state.stats.streak}<span> dias de ofensiva</span></div><p class="muted">${state.stats.today?'Ofensiva de hoje concluída. Bom trabalho!':'Conclua todas as séries de pelo menos 3 exercícios e finalize o treino.'}</p>${week()}<p class="subtle">Dias consecutivos de calendário. Respeite os dias de descanso, mesmo que a sequência reinicie.</p></section></div><div class="grid three" style="margin-top:20px"><div class="panel"><small>Peso mais recente</small><div class="metric">${esc(latestWeight()||'—')}<span> kg</span></div><small>Meta informada: ${esc(state.profile.settings?.target||'—')} kg</small></div><div class="panel"><small>Dias treinados</small><div class="metric">${state.stats.total}<span> dias</span></div><small>Uma contagem por dia válido</small></div><div class="panel"><small>Seu foco</small><h3 style="margin:17px 0">${esc(state.profile.settings?.goal||'Defina seu objetivo')}</h3>${button('Ajustar perfil','profile','ghost')}</div></div><div class="section-title"><h2>Alimentação no seu horário</h2>${button('Ver refeições','nav','ghost','data-route="food"')}</div><section class="panel">${items('meal').sort((a,b)=>(a.data.time||'').localeCompare(b.data.time||'')).map(r=>`<div class="row"><div><span class="meal-time">${esc(r.data.time)}</span></div><div style="flex:1"><h3>${esc(r.data.name)}</h3><p class="muted">${esc(r.data.content)}</p></div></div>`).join('')||'<p class="empty">Cadastre suas refeições para acompanhar aqui.</p>'}</section>`}
function latestWeight(){return items('measurement').sort((a,b)=>b.data.date.localeCompare(a.data.date))[0]?.data.weight}
function workouts(){if(state.draft)return liveWorkout();return head('Seu treino. Seu ritmo.','Fichas que você pode ajustar e acompanhar.',button('Criar ficha','new-routine','primary')+button('Auxiliar IA','nav','ghost','data-route="ai"'))+`<div class="grid three">${items('routine').map(r=>`<section class="panel"><div class="card-top"><span class="letter">${esc(r.data.group||'•')}</span><div><h3>${esc(r.data.name)}</h3><small>${r.data.exercises.length} exercícios</small></div></div>${r.data.exercises.slice(0,4).map(e=>`<p class="muted">${esc(e.name)} <small>· ${e.sets.length} séries</small></p>`).join('')}${r.data.exercises.length>4?`<small>+ ${r.data.exercises.length-4} exercícios</small>`:''}<div class="card-footer">${button('Iniciar','start','primary',`data-id="${r.id}"`)}${button('Editar','edit-routine','ghost',`data-id="${r.id}"`)}${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</div></section>`).join('')}</div>${!items('routine').length?`<section class="panel empty"><p>Seu espaço de treino está pronto para receber as primeiras fichas.</p>${button('Adicionar fichas ABC de exemplo','seed-routines','primary')}<p class="subtle">Exemplos educativos. Ajuste com seu professor.</p></section>`:''}<div class="section-title"><h2>Histórico de sessões</h2></div><section class="panel">${items('workout').sort((a,b)=>new Date(b.data.finished_at)-new Date(a.data.finished_at)).map(r=>`<div class="row"><div><h3>${esc(r.data.name)}</h3><small>${new Date(r.data.finished_at).toLocaleString('pt-BR')} · ${completed(r.data)} exercícios concluídos · ${qualifies(r.data)?'dia válido':'sessão parcial'}</small></div><div class="actions">${button('Revisar','review-workout','ghost',`data-id="${r.id}"`)}${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</div></div>`).join('')||'<p class="empty">Suas sessões aparecerão aqui depois de finalizar.</p>'}</section>`}
function liveWorkout(){const d=state.draft.data,total=d.exercises.reduce((n,e)=>n+e.sets.length,0),done=d.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0);return head(esc(d.name),'Registre cada série e avance com controle.',button('Editar sessão','edit-session','ghost'))+`<div class="workbar"><div><small>Tempo de treino</small><div class="time" data-elapsed>00:00</div></div><div><small>Descanso</small><div class="time" data-rest>—</div></div>${button('Descansar 90 s','rest','ghost')}${button('Pular descanso','skip-rest','ghost')}${button('Finalizar','finish','primary')}</div><small data-sync>${esc(state.sync)}</small><div class="progress"><div style="width:${total?done/total*100:0}%"></div></div><p class="muted">${done}/${total} séries · ${completed(d)}/3 exercícios para a ofensiva do dia</p>${!state.demo&&localStorage.getItem('forma-draft-'+state.user.id)?button('Resolver rascunho local','recover-draft','ghost'):''}${d.exercises.map((e,i)=>`<section class="panel exercise"><div class="card-top"><span class="letter">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><small>${e.sets.length} séries · descanso ${esc(e.rest||90)} s ${e.name==='Prancha'?'· reps = segundos':''}</small></div></div><details><summary>Como executar e para que serve</summary><p>${esc(e.purpose||'Descrição ainda não cadastrada.')}</p><p>${esc(e.execution||'Peça orientação ao seu professor.')}</p><p class="muted">Alternativa: ${esc(e.alternative||'Consulte seu professor.')}</p>${button('Ouvir explicação','speak-ex','ghost',`data-ex="${i}"`)}</details><div class="set-head"><span>Série</span><span>Carga (kg)</span><span>${e.name==='Prancha'?'Segundos':'Reps'}</span><span>Feita</span></div>${e.sets.map((s,j)=>`<div class="set-row ${s.done?'done':''}"><span>${j+1}</span><input type="number" min="0" max="1000" step="0.5" value="${s.kg}" aria-label="Carga da série ${j+1} de ${esc(e.name)}" data-live="kg" data-ex="${i}" data-set="${j}"><input type="number" min="1" max="200" value="${s.reps}" aria-label="Repetições da série ${j+1} de ${esc(e.name)}" data-live="reps" data-ex="${i}" data-set="${j}">${button(s.done?'✓':'○','set-done',s.done?'primary':'ghost',`data-ex="${i}" data-set="${j}" aria-label="${s.done?'Desmarcar':'Concluir'} série ${j+1}" aria-pressed="${s.done}"`)}</div>`).join('')}</section>`).join('')}<div class="actions">${button('Salvar e sair do treino','leave-session','ghost')}${button('Descartar sessão','discard-session','danger ghost')}</div>`}
function food(){return head('Alimentação possível.','Seu cardápio a partir do que você tem e pode comprar.',button('Nova refeição','new-meal','primary'))+`<div class="grid two"><section class="grid">${items('meal').sort((a,b)=>(a.data.time||'').localeCompare(b.data.time||'')).map(r=>`<article class="panel"><div class="card-top"><span class="meal-time">${esc(r.data.time)}</span><h3>${esc(r.data.name)}</h3></div><p>${esc(r.data.content)}</p><p class="muted">${esc(r.data.purpose)}</p><div class="actions">${button('Editar','edit-meal','ghost',`data-id="${r.id}"`)}${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</div></article>`).join('')||`<div class="panel empty"><p>Cadastre seu plano alimentar ou peça uma sugestão ao auxiliar.</p>${button('Adicionar horários de exemplo','seed-meals','ghost')}</div>`}</section><aside><div class="panel"><div class="section-title" style="margin-top:0"><h2>Minha despensa</h2>${button('+','new-pantry','primary','aria-label="Adicionar alimento"')}</div><p class="muted">O auxiliar consulta esta lista e seu orçamento.</p>${items('pantry').map(r=>`<div class="row"><div><h3>${esc(r.data.name)}</h3><small>${r.data.available?'Tenho em casa':'Posso comprar'} · ${esc(r.data.quantity)} ${esc(r.data.unit)} ${Number(r.data.price)>0?'· R$ '+Number(r.data.price).toFixed(2):''}</small></div><div class="actions">${button('Editar','edit-pantry','ghost',`data-id="${r.id}"`)}${button('✕','delete-record','ghost danger',`data-id="${r.id}" aria-label="Excluir ${esc(r.data.name)}"`)}</div></div>`).join('')||'<p class="empty">Adicione seus alimentos disponíveis.</p>'}<p class="subtle">Orçamento semanal informado: ${Number(state.profile.settings?.budget)>0?'R$ '+Number(state.profile.settings.budget).toFixed(2):'não informado'}</p></div><div class="notice">As sugestões da IA precisam de revisão. Porções devem indicar peso cru ou cozido. Não tratamos substituições como nutricionalmente idênticas.</div></aside></div>`}
function progress(){const rows=items('measurement').sort((a,b)=>a.data.date.localeCompare(b.data.date));return head('Evolução que você acompanha.','Compare medidas, desempenho e fotos no seu ritmo.',button('Registrar medidas','new-measurement','primary'))+`<div class="grid two"><section class="panel"><h2>Peso ao longo do tempo</h2><p class="muted">Meta informada: ${esc(state.profile.settings?.target||'—')} kg. O peso sozinho não distingue músculo de gordura.</p><div class="chart">${rows.slice(-10).map(r=>`<div class="bar" style="height:${Math.min(100,Number(r.data.weight)/Math.max(...rows.map(x=>Number(x.data.weight)))*100)}%" title="${esc(r.data.date)}: ${esc(r.data.weight)} kg"><small>${esc(r.data.weight)}</small></div>`).join('')||'<p class="empty">Registre sua primeira medida.</p>'}</div><small>Últimos ${Math.min(rows.length,10)} registros · ordem cronológica · barras a partir de zero</small></section><section class="panel"><h2>Constância</h2><div class="metric">${state.stats.total}<span> dias treinados</span></div>${week()}<p class="subtle">Um dia só conta após finalizar pelo menos 3 exercícios completos.</p></section></div><div class="section-title"><h2>Medidas corporais</h2></div><section class="panel table-wrap"><table><thead><tr><th>Data</th><th>Peso</th><th>Cintura</th><th>Coxa</th><th>Braço</th><th>Ações</th></tr></thead><tbody>${rows.reverse().map(r=>`<tr><td>${esc(r.data.date)}</td><td>${esc(r.data.weight)} kg</td><td>${esc(r.data.waist||'—')} cm</td><td>${esc(r.data.thigh||'—')} cm</td><td>${esc(r.data.arm||'—')} cm</td><td>${button('Editar','edit-measurement','ghost',`data-id="${r.id}"`)} ${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></section><div class="section-title"><h2>Fotos privadas</h2><div class="actions">${button('Atualizar','load-photos','ghost')}${button('Enviar foto','upload-photo','primary')}</div></div><p class="muted">Só você pode acessar. Fotos não são compartilhadas com amigos nem enviadas à IA automaticamente.</p><div class="photos">${state.photos.map(p=>`<article class="panel"><img src="${esc(p.url)}" alt="${esc(p.caption||'Registro de evolução')}" loading="lazy"><p>${esc(p.caption)}</p><small>${new Date(p.created_at).toLocaleDateString('pt-BR')}</small><div class="card-footer">${button('Legenda','edit-photo','ghost',`data-id="${p.id}"`)}${button('Excluir','delete-photo','ghost danger',`data-id="${p.id}"`)}</div></article>`).join('')||'<div class="panel empty">Carregue ou envie suas fotos.</div>'}</div>`}
function friends(){return head('Evoluir em boa companhia.','Encontre amigos pelo nome de usuário e compartilhe sua constância.',button('Atualizar','refresh-friends','ghost'))+`<div class="grid two"><section class="panel"><h2>Seu círculo</h2>${state.friends.map(f=>`<div class="row"><div class="userline"><span class="avatar">${esc(f.name?.slice(0,1).toUpperCase())}</span><div><h3>${esc(f.name)}</h3><small>@${esc(f.username)}</small><p class="muted">${f.status==='pending'?(f.incoming?'Convite recebido':'Convite enviado'):f.progress?`♨ ${f.progress.streak} dias de ofensiva · ${f.progress.total} dias treinados ${f.progress.today?'· treinou hoje':''}`:'Progresso privado'}</p></div></div><div class="actions">${f.status==='pending'&&f.incoming?button('Aceitar','accept-friend','primary',`data-id="${f.id}"`):''}${button(f.status==='accepted'?'Remover':'Cancelar','delete-friend','ghost danger',`data-id="${f.id}"`)}</div></div>`).join('')||'<p class="empty">Seu círculo começa com um convite. Busque sua esposa ou seus amigos pelo @usuário.</p>'}</section><section class="panel"><h2>Encontrar pessoas</h2><form id="people-form" class="form">${field('q','Nome de usuário','','text','required minlength="2" placeholder="ex.: walyson"')}<button type="submit" class="primary">Buscar</button></form><div id="people-results"></div><div class="notice">Seu nome e @usuário aparecem na busca. Amigos aceitos só veem sua ofensiva e total de dias se você ativar o compartilhamento no perfil.</div><label class="check"><input type="checkbox" id="share-progress" ${state.profile.share_progress?'checked':''}>Compartilhar meu progresso com amigos</label></section></div>`}
function ai(){return head('Seu auxiliar, com contexto.','Treino e alimentação com base na sua rotina.')+`<div class="grid two"><section class="panel"><div class="ai-mark"><span class="avatar">✦</span><div><h2 style="margin:0">Auxiliar Forma</h2><small>Gemini · sugestões para você revisar</small></div></div><form id="ai-form" class="form"><label>O que vamos organizar?<select name="mode"><option value="chat">Conversar e tirar dúvidas</option><option value="training_plan">Propor treino ABC completo</option><option value="routine">Propor uma ficha de treino</option><option value="meal_plan">Propor alimentação do dia</option><option value="meal">Propor uma refeição</option></select></label>${area('prompt','Sua mensagem','')}<div class="actions">${button('🎙 Ditar mensagem','dictate','ghost')}${button('Entender meu perfil','assess','ghost')}</div><label class="check"><input type="checkbox" name="consent" required>Autorizo enviar meu perfil, fichas, medidas e despensa ao Gemini para este pedido.</label><label>Foto para comparar (opcional)<select name="photo_id"><option value="">Nenhuma foto</option>${state.photos.map(p=>`<option value="${p.id}">${esc(p.caption||new Date(p.created_at).toLocaleDateString('pt-BR'))}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="photo_consent">Também autorizo enviar a foto escolhida ao Gemini.</label><p class="error" data-error></p><button type="submit" class="primary">Enviar ao auxiliar</button></form><p class="subtle">Ditado e leitura usam recursos de voz do navegador, quando disponíveis. A IA não identifica biotipo como diagnóstico.</p></section><section class="panel"><h2>Sua resposta</h2>${state.ai?`<div class="chat">${esc(state.ai.answer)}</div><div class="actions" style="margin-top:20px">${button('Ouvir resposta','speak-ai','ghost')}${button('Parar áudio','stop-audio','ghost')}${state.ai.proposal?button('Revisar proposta','apply-ai','primary'):''}</div>`:'<p class="empty">Descreva seu objetivo ou peça uma alternativa para um exercício. O auxiliar consultará os dados que você autorizar.</p>'}<div class="notice">“Ectomorfo” pode ser uma autodescrição. O planejamento considera experiência, alimentação, recuperação e desempenho. Dor, lesões ou condições de saúde precisam de avaliação profissional.</div></section></div>`}
const views={today,workouts,food,progress,friends,ai};
function bindView(){for(const input of app.querySelectorAll('[data-live]'))input.oninput=()=>{const e=state.draft.data.exercises[Number(input.dataset.ex)],s=e.sets[Number(input.dataset.set)];s[input.dataset.live]=Number(input.value);changed()};
 const pf=app.querySelector('#people-form');if(pf)pf.onsubmit=async e=>{e.preventDefault();const q=new FormData(pf).get('q'),b=pf.querySelector('button');b.disabled=true;try{if(state.demo)throw new Error('A busca real será ativada após configurar Supabase.');const rows=await api('people?q='+encodeURIComponent(q));app.querySelector('#people-results').innerHTML=rows.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><br><small>@${esc(p.username)}</small></div>${button('Adicionar','add-friend','primary',`data-id="${p.id}"`)}</div>`).join('')||'<p class="empty">Nenhum usuário encontrado.</p>'}catch(err){toast(err.message)}finally{b.disabled=false}};
 const share=app.querySelector('#share-progress');if(share)share.onchange=async()=>{const next=share.checked;try{if(state.demo){state.profile.share_progress=next;demoPersist()}else state.profile=await api('profile','PATCH',{share_progress:next});toast(next?'Progresso visível para amigos aceitos.':'Progresso privado.')}catch(e){share.checked=!next;toast(e.message)}};
 const af=app.querySelector('#ai-form');if(af)af.onsubmit=async e=>{e.preventDefault();const b=af.querySelector('[type=submit]');b.disabled=true;b.textContent='Organizando sua resposta…';try{if(state.demo)throw new Error('Configure Gemini e Supabase para usar o auxiliar real.');const data=Object.fromEntries(new FormData(af));data.consent=data.consent==='on';data.photo_consent=data.photo_consent==='on';state.ai=await api('ai','POST',data);render()}catch(err){af.querySelector('[data-error]').textContent=err.message}finally{b.disabled=false;b.textContent='Enviar ao auxiliar'}};
}
function routineEditor(record=null,session=false,proposal=null){let data=clone(proposal||record?.data||{name:'',group:'A',exercises:[]});
 function editor(){formModal(session?'Editar esta sessão':record?'Editar ficha':'Criar ficha',field('name','Nome da ficha',data.name,'text','required maxlength="100"')+`<label>Grupo<select name="group">${['A','B','C','Outro'].map(x=>`<option ${data.group===x?'selected':''}>${x}</option>`).join('')}</select></label><div id="exercise-list">${data.exercises.map((e,i)=>`<div class="row"><div><strong>${esc(e.name)}</strong><br><small>${e.sets.length} séries · ${e.sets[0]?.reps||10} reps · ${e.rest||90}s descanso</small></div><div class="actions">${button('Editar','ex-edit','ghost',`data-index="${i}"`)}${button('↑','ex-up','ghost',`data-index="${i}" aria-label="Mover acima"`)}${button('✕','ex-delete','ghost danger',`data-index="${i}" aria-label="Remover exercício"`)}</div></div>`).join('')}</div>${button('Adicionar exercício','ex-add','ghost')}`,async f=>{data.name=f.name;data.group=f.group;if(!data.exercises.length)throw new Error('Adicione pelo menos um exercício.');if(session){state.draft.data={...state.draft.data,...data};changed();await saveDraft()}else await put('routine',data,record?.id,record?.version);toast('Ficha salva.');});
 const saveHeader=()=>{data.name=modal.querySelector('[name=name]').value;data.group=modal.querySelector('[name=group]').value};
 modal.querySelectorAll('[data-action^="ex-"]').forEach(b=>b.onclick=()=>{saveHeader();const i=Number(b.dataset.index);if(b.dataset.action==='ex-delete'){data.exercises.splice(i,1);editor()}else if(b.dataset.action==='ex-up'){if(i>0)[data.exercises[i-1],data.exercises[i]]=[data.exercises[i],data.exercises[i-1]];editor()}else exEditor(b.dataset.action==='ex-add'?null:i)});
 }
 function exEditor(i){const e=i===null?{name:'',purpose:'',execution:'',alternative:'',sets:[{kg:0,reps:10,done:false}],rest:90}:data.exercises[i];const library=starterRoutines().flatMap(r=>r.exercises);formModal('Exercício',`<label>Preencher a partir de um exemplo<select id="exercise-example"><option value="">Personalizado</option>${library.map((e,j)=>`<option value="${j}">${esc(e.name)}</option>`).join('')}</select></label>`+field('name','Nome',e.name,'text','required')+field('sets','Número de séries',e.sets.length,'number','required min="1" max="10"')+field('reps','Repetições por série',e.sets[0]?.reps||10,'number','required min="1" max="200"')+field('rest','Descanso (segundos)',e.rest||90,'number','required min="10" max="600"')+area('purpose','Para que serve',e.purpose)+area('execution','Como executar',e.execution)+field('alternative','Alternativa',e.alternative),async f=>{const n=Number(f.sets);if(n<1||n>10)throw new Error('Use de 1 a 10 séries.');const next={...e,id:e.id||uid(),name:f.name,purpose:f.purpose,execution:f.execution,alternative:f.alternative,rest:Number(f.rest),sets:Array.from({length:n},(_,j)=>e.sets[j]?{...e.sets[j],reps:Number(f.reps)!==Number(e.sets[0]?.reps)?Number(f.reps):e.sets[j].reps}:{kg:0,reps:Number(f.reps),done:false})};if(i===null)data.exercises.push(next);else data.exercises[i]=next;setTimeout(editor,0)},'Adicionar à ficha');modal.querySelector('#exercise-example').onchange=ev=>{if(ev.target.value==='')return;const x=library[Number(ev.target.value)];for(const k of ['name','purpose','execution','alternative','rest'])modal.querySelector(`[name=${k}]`).value=x[k];modal.querySelector('[name=sets]').value=x.sets.length;modal.querySelector('[name=reps]').value=x.sets[0].reps};}
 editor();}
function recordEditor(kind,r=null,proposal=null){const d=proposal||r?.data||{};let html;if(kind==='meal')html=field('name','Nome da refeição',d.name,'text','required')+field('time','Horário',d.time||'12:00','time','required')+area('content','Alimentos, porções e preparo',d.content)+area('purpose','Finalidade e observações',d.purpose);if(kind==='pantry')html=field('name','Alimento',d.name,'text','required')+field('quantity','Quantidade disponível ou planejada',d.quantity??1,'number','required min="0" step="0.01"')+field('unit','Unidade (g, kg, un)',d.unit||'un','text','required')+field('price','Preço estimado dessa quantidade (R$)',d.price||0,'number','min="0" step="0.01"')+`<label class="check"><input type="checkbox" name="available" ${d.available!==false?'checked':''}>Tenho em casa (desmarque se apenas pode comprar)</label>`;if(kind==='measurement')html=field('date','Data',d.date||new Date().toISOString().slice(0,10),'date','required')+field('weight','Peso (kg)',d.weight||latestWeight()||'','number','required min="1" max="499" step="0.1"')+[['waist','Cintura'],['belly','Barriga'],['chest','Peitoral'],['hip','Glúteo'],['neck','Pescoço'],['thigh','Coxa'],['relaxed_arm','Braço relaxado'],['arm','Braço contraído'],['forearm','Antebraço'],['calf','Panturrilha']].map(([k,l])=>field(k,l+' (cm)',d[k]||'','number','min="0" max="300" step="0.1"')).join('')+area('notes','Observações',d.notes);formModal(r?'Editar registro':`Novo registro: ${kind==='meal'?'refeição':kind==='pantry'?'alimento':'medidas'}`,html,async(f,form)=>{for(const k of ['weight','quantity','price','waist','belly','chest','hip','neck','thigh','relaxed_arm','arm','forearm','calf'])if(k in f)f[k]=f[k]===''?null:Number(f[k]);if(kind==='pantry')f.available=form.querySelector('[name=available]').checked;await put(kind,f,r?.id,r?.version);toast('Registro salvo.');});}
function profileEditor(){const p=state.profile,s=p.settings||{};const html=field('name','Seu nome',p.name,'text','required maxlength="80"')+field('username','Nome de usuário',p.username,'text','required pattern="[a-z0-9_]{3,24}"')+field('password','Senha atual (obrigatória se alterar nome ou usuário)','','password','autocomplete="current-password"')+field('age','Idade',s.age,'number','min="18" max="100"')+field('height','Altura (cm)',s.height,'number','min="100" max="250"')+field('weight','Peso de referência (kg)',s.weight,'number','min="1" max="499" step="0.1"')+field('target','Meta de peso (kg)',s.target,'number','min="1" max="499" step="0.1"')+field('goal','Objetivo e prioridades',s.goal)+`<label>Biotipo autodeclarado<select name="biotype">${['Não sei','Ectomorfo (autodeclarado)','Mesomorfo (autodeclarado)','Endomorfo (autodeclarado)','Prefiro não classificar'].map(x=>`<option ${s.biotype===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="subtle">Essa classificação não determina seu treino. O auxiliar ajuda a entender seu perfil, sem diagnosticar pelo corpo ou pelas fotos.</p><label>Experiência<select name="experience">${['Iniciante','Intermediário','Avançado'].map(x=>`<option ${s.experience===x?'selected':''}>${x}</option>`).join('')}</select></label>`+field('minutes','Tempo disponível por sessão (min)',s.minutes||60,'number','min="15" max="180"')+field('days','Dias de treino por semana',s.days||3,'number','min="1" max="6"')+field('equipment','Equipamentos disponíveis',s.equipment)+area('limitations','Dores, lesões, condições de saúde e restrições alimentares',s.limitations)+field('budget','Orçamento semanal para alimentação (R$)',s.budget||0,'number','min="0" step="0.01"')+field('sleep','Horas de sono habituais',s.sleep||'','number','min="0" max="16" step="0.5"')+area('schedule','Horários e rotina',s.schedule)+`<div class="notice">E-mail: ${esc(state.user.email)}. Fotos e medidas ficam privadas. Compartilhar progresso é opcional.</div><div class="actions">${button('Alterar e-mail ou senha','account-edit','ghost')}${button('Excluir conta','delete-account','ghost danger')}</div>`;formModal('Meu perfil',html,async f=>{const settings={};for(const k of ['age','height','weight','target','minutes','days','budget','sleep'])settings[k]=f[k]===''?null:Number(f[k]);for(const k of ['goal','biotype','experience','equipment','limitations','schedule'])settings[k]=f[k];if(state.demo){state.profile={...p,name:f.name,username:f.username,settings};demoPersist()}else{const b={settings};if(f.name!==p.name)b.name=f.name;if(f.username!==p.username)b.username=f.username;if(b.name||b.username)b.password=f.password;state.profile=await api('profile','PATCH',b)}toast('Perfil atualizado.');});}
function speak(text){if(!('speechSynthesis'in window)){toast('Leitura em voz não disponível neste navegador.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='pt-BR';u.rate=1;speechSynthesis.speak(u)}
async function start(id){if(state.draft){state.route='workouts';render();return}const r=state.records.find(r=>r.id===id);if(!r)throw new Error('Ficha não encontrada.');const data=clone(r.data);const last=items('workout').filter(x=>x.data.name===data.name).sort((a,b)=>new Date(b.data.finished_at)-new Date(a.data.finished_at))[0];for(const e of data.exercises){const prev=last?.data.exercises.find(x=>x.id===e.id);for(let j=0;j<e.sets.length;j++){if(prev?.sets[j]){e.sets[j].kg=prev.sets[j].kg;e.sets[j].reps=prev.sets[j].reps;}e.sets[j].done=false;}}data.started_at=new Date().toISOString();data.log_id=uid();state.draft={id:uid(),kind:'draft',data};state.dirty=true;state.route='workouts';cacheDraft();render();await saveDraft()}
function updateTimes(){if(!state.draft)return;const now=Date.now(),elapsed=Math.max(0,Math.floor((now-new Date(state.draft.data.started_at))/1000));for(const e of document.querySelectorAll('[data-elapsed]'))e.textContent=duration(elapsed);const end=state.draft.data.rest_until,left=end?Math.max(0,Math.ceil((end-now)/1000)):0;for(const e of document.querySelectorAll('[data-rest]'))e.textContent=end?(left?duration(left):'Pronto'):'—';}
function duration(s){return (Math.floor(s/60)).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0')}
setInterval(updateTimes,1000);
setInterval(async()=>{if(!state.user||state.demo||document.hidden||modal.open||state.route!=='friends'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{state.friends=await api('friends');state.stats=await api('stats');render()}catch{}},30000);
async function confirmAction(title,text,fn,label='Confirmar'){formModal(title,`<p>${esc(text)}</p>`,async()=>{await fn()},label)}
async function refreshStats(){if(state.demo)demoStats();else state.stats=await api('stats')}
async function loadPhotos(){if(state.demo)throw new Error('Fotos privadas estarão disponíveis com Supabase configurado.');state.photos=await api('photos');render()}
const actions={
 'close':()=>modal.close(),'auth-login':()=>auth(),'auth-signup':()=>auth('signup'),'auth-recover':()=>auth('recover'),'demo':enterDemo,
 'nav':b=>{state.route=b.dataset.route;render()},'continue':()=>{state.route='workouts';render()},'start':b=>start(b.dataset.id),
 'profile':profileEditor,'new-routine':()=>routineEditor(),'edit-routine':b=>routineEditor(state.records.find(r=>r.id===b.dataset.id)),
 'new-meal':()=>recordEditor('meal'),'new-pantry':()=>recordEditor('pantry'),'new-measurement':()=>recordEditor('measurement'),
 'edit-meal':b=>recordEditor('meal',state.records.find(r=>r.id===b.dataset.id)),'edit-pantry':b=>recordEditor('pantry',state.records.find(r=>r.id===b.dataset.id)),'edit-measurement':b=>recordEditor('measurement',state.records.find(r=>r.id===b.dataset.id)),
 'seed-routines':async()=>{for(const d of starterRoutines())await put('routine',d);render();toast('Exemplos ABC adicionados. Revise antes de treinar.')},
 'seed-meals':async()=>{for(const d of baseMeals)await put('meal',d);render();toast('Horários de exemplo adicionados.')},
 'delete-record':b=>confirmAction('Excluir registro?','Esta ação remove o registro. Excluir uma sessão pode alterar a ofensiva.',async()=>{await remove(b.dataset.id);await refreshStats();toast('Registro excluído.')},'Excluir'),
 'rest':()=>{state.draft.data.rest_until=Date.now()+90000;changed();updateTimes()},'skip-rest':()=>{state.draft.data.rest_until=null;changed();updateTimes()},
 'set-done':b=>{const e=state.draft.data.exercises[Number(b.dataset.ex)],s=e.sets[Number(b.dataset.set)];if(!(s.reps>0&&s.reps<=200&&s.kg>=0&&s.kg<=1000))throw new Error('Informe carga e repetições válidas antes de concluir.');s.done=!s.done;if(s.done)state.draft.data.rest_until=Date.now()+(e.rest||90)*1000;changed();render()},
 'speak-ex':b=>{const e=state.draft.data.exercises[Number(b.dataset.ex)];speak(e.name+'. '+e.purpose+'. '+e.execution)},
 'edit-session':()=>routineEditor(state.draft,true),
 'leave-session':async()=>{await saveDraft();state.route='today';render()},
 'discard-session':()=>confirmAction('Descartar sessão?','As séries desta sessão serão removidas. Sua ficha original permanece.',async()=>{clearTimeout(saveTimer);if(savePromise)await savePromise;if(state.records.some(r=>r.id===state.draft.id))await remove(state.draft.id);state.draft=null;state.dirty=false;localStorage.removeItem('forma-draft-'+state.user.id);if(state.demo)demoPersist();toast('Sessão descartada.')},'Descartar'),
 'finish':()=>{const n=completed(state.draft.data);confirmAction('Finalizar treino?',`${n} exercícios completos. ${n>=3?'Este treino atende ao mínimo da ofensiva.':'A sessão será registrada, mas não contará para a ofensiva.'}`,async()=>{clearTimeout(saveTimer);await saveDraft();const d=clone(state.draft.data);await put('workout',d,d.log_id);await remove(state.draft.id);state.draft=null;state.dirty=false;localStorage.removeItem('forma-draft-'+state.user.id);await refreshStats();if(state.demo)demoPersist();toast(n>=3?'Treino concluído. Mais um dia de constância!':'Sessão registrada. Respeite seu ritmo.');},'Finalizar')},
 'review-workout':b=>{const r=state.records.find(r=>r.id===b.dataset.id);formModal('Revisar sessão',`<p class="muted">A data de conclusão é preservada. Alterar séries recalcula a ofensiva.</p>${r.data.exercises.map((e,i)=>`<div class="list-editor"><h3>${esc(e.name)}</h3>${e.sets.map((s,j)=>`<div class="set-row"><span>${j+1}</span><input type="number" name="kg_${i}_${j}" value="${s.kg}" min="0" max="1000" step="0.5" aria-label="Carga"><input type="number" name="reps_${i}_${j}" value="${s.reps}" min="1" max="200" aria-label="Repetições"><input type="checkbox" name="done_${i}_${j}" ${s.done?'checked':''} aria-label="Série concluída"></div>`).join('')}</div>`).join('')}`,async f=>{const d=clone(r.data);d.exercises.forEach((e,i)=>e.sets.forEach((s,j)=>{s.kg=Number(f[`kg_${i}_${j}`]);s.reps=Number(f[`reps_${i}_${j}`]);s.done=f[`done_${i}_${j}`]==='on'}));await put('workout',d,r.id,r.version);await refreshStats();toast('Sessão atualizada.')});},
 'recover-draft':()=>{const c=JSON.parse(localStorage.getItem('forma-draft-'+state.user.id)||'null');if(!c?.dirty)throw new Error('Não há rascunho pendente.');formModal('Resolver rascunho',`<p>Você pode carregar a versão atual da nuvem ou aplicar seu rascunho local sobre ela. Revise antes de substituir alterações de outro aparelho.</p><label>Versão<select name="choice"><option value="cloud">Usar versão da nuvem</option><option value="local">Aplicar meu rascunho local</option></select></label>`,async f=>{const rows=await api('records'),cloud=rows.find(r=>r.kind==='draft');state.records=rows;if(f.choice==='local'){if(cloud&&cloud.id!==c.draft.id)throw new Error('A nuvem possui outra sessão. Finalize ou descarte antes de aplicar este rascunho.');state.draft={...c.draft,version:cloud?.version};state.dirty=true;await saveDraft()}else{state.draft=cloud||null;state.dirty=false;localStorage.removeItem('forma-draft-'+state.user.id);state.sync='Salvo na nuvem'}toast('Versão escolhida.');});},
 'refresh-friends':async()=>{if(state.demo)throw new Error('Amizades reais precisam do Supabase.');state.friends=await api('friends');render()},
 'add-friend':async b=>{await api('friends','POST',{target:b.dataset.id});state.friends=await api('friends');render();toast('Convite enviado.')},
 'accept-friend':async b=>{await api('friends/'+b.dataset.id,'PATCH',{});state.friends=await api('friends');render();toast('Convite aceito.')},
 'delete-friend':b=>confirmAction('Remover convite ou amizade?','O progresso deixará de ser compartilhado com essa pessoa.',async()=>{await api('friends/'+b.dataset.id,'DELETE');state.friends=await api('friends')},'Remover'),
 'load-photos':loadPhotos,
 'upload-photo':()=>{if(state.demo)throw new Error('Envio de fotos precisa do Supabase.');formModal('Enviar foto privada',`<label>Foto (JPG, PNG ou WebP, até 8 MB)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label>${field('caption','Legenda','','text','maxlength="160"')}<p class="subtle">A imagem será reprocessada neste aparelho para retirar metadados antes do envio.</p>`,async(f,form)=>{const file=form.querySelector('[name=photo]').files[0];if(!file||file.size>8388608)throw new Error('Limite de 8 MB por foto.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw new Error('Não foi possível processar a imagem.');await api('photos?caption='+encodeURIComponent(f.caption),'POST',blob);state.photos=await api('photos');toast('Foto privada enviada.');},'Enviar');},
 'edit-photo':b=>{const p=state.photos.find(p=>p.id===b.dataset.id);formModal('Editar legenda',field('caption','Legenda',p.caption,'text','maxlength="160"'),async f=>{await api('photos/'+p.id,'PATCH',f);state.photos=await api('photos')})},
 'delete-photo':b=>confirmAction('Excluir foto?','Esta foto será removida do armazenamento privado.',async()=>{await api('photos/'+b.dataset.id,'DELETE');state.photos=await api('photos')},'Excluir'),
 'speak-ai':()=>speak(state.ai?.answer||''),'stop-audio':()=>window.speechSynthesis?.cancel(),
 'assess':()=>{app.querySelector('[name=prompt]').value='Ajude a entender meu perfil para hipertrofia. Não sei meu biotipo. Explique por que essa classificação não basta e quais informações faltam sobre minha experiência, recuperação, alimentação e equipamentos. Faça perguntas objetivas antes de propor treino ou refeições.';app.querySelector('[name=mode]').value='chat'},
 'dictate':()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)throw new Error('Ditado não disponível. Use o microfone do teclado do celular.');openModal('Ditar mensagem',`<p>O reconhecimento de voz do navegador pode enviar seu áudio ao provedor dele. Grave apenas se concordar. A transcrição preencherá sua mensagem para você revisar.</p>${button('Iniciar ditado','start-dictation','primary')}`);modal.querySelector('[data-action=start-dictation]').onclick=()=>{const recognition=new Speech();recognition.lang='pt-BR';recognition.onresult=e=>{app.querySelector('[name=prompt]').value=e.results[0][0].transcript;toast('Mensagem transcrita. Revise antes de enviar.')};recognition.onerror=()=>toast('Não foi possível reconhecer. Verifique a permissão do microfone.');recognition.start();modal.close();toast('Ouvindo…')};},
 'apply-ai':()=>{const p=state.ai?.proposal;if(!p)throw new Error('Não há proposta para revisar.');if(Array.isArray(p.routines)||Array.isArray(p.meals)){const arr=p.routines||p.meals;openModal('Revisar propostas',`<p>Revise e salve cada ficha ou refeição. Nada foi aplicado automaticamente.</p>${arr.map((x,i)=>`<div class="row"><strong>${esc(x.name||'Proposta')}</strong>${button('Revisar','review-proposal','primary',`data-index="${i}"`)}</div>`).join('')}`);modal.querySelectorAll('[data-action=review-proposal]').forEach(b=>b.onclick=()=>{const x=arr[Number(b.dataset.index)];const previous=state.ai.proposal;state.ai.proposal=x;try{actions['apply-ai']()}finally{state.ai.proposal=previous}});return;}if(Array.isArray(p.exercises)){const data={name:String(p.name||'Proposta de treino'),group:['A','B','C'].includes(p.group)?p.group:'A',exercises:p.exercises.slice(0,20).map(e=>({id:uid(),name:String(e.name||'Exercício'),purpose:String(e.purpose||''),execution:String(e.execution||''),alternative:String(e.alternative||''),rest:Math.min(180,Math.max(30,Number(e.rest)||90)),sets:Array.from({length:Math.min(5,Math.max(1,Number(e.sets)||3))},()=>({kg:0,reps:Math.min(20,Math.max(6,Number(e.reps)||10)),done:false}))}))};routineEditor(null,false,data)}else if(p.content)recordEditor('meal',null,{name:String(p.name||'Proposta de refeição'),time:/^\d{2}:\d{2}$/.test(p.time)?p.time:'12:00',content:String(p.content),purpose:String(p.purpose||'')});else throw new Error('Proposta sem formato utilizável. Peça novamente ao auxiliar.');},
 'account-edit':()=>{if(state.demo)throw new Error('A demonstração não tem senha real.');formModal('Alterar e-mail ou senha',field('password','Senha atual','','password','required autocomplete="current-password"')+field('email','Novo e-mail (opcional)','','email')+field('new_password','Nova senha (opcional, mínimo 10 caracteres)','','password','minlength="10" autocomplete="new-password"'),async f=>{if(!f.email&&!f.new_password)throw new Error('Informe o novo e-mail ou a nova senha.');await api('account','PATCH',f);toast('Alteração solicitada. Confirme o novo e-mail pelo link recebido, se aplicável.');});},
 'delete-account':()=>{if(state.demo)throw new Error('A demonstração não possui uma conta real.');formModal('Excluir minha conta',`<p>Isso remove perfil, fichas, refeições, registros, amizades e fotos. A exclusão é definitiva.</p>${field('password','Senha atual','','password','required autocomplete="current-password"')}${field('confirm','Digite EXCLUIR','','text','required')}`,async f=>{if(f.confirm!=='EXCLUIR')throw new Error('Digite EXCLUIR para confirmar.');await api('account','DELETE',f);clearPrivateCache();state.user=null;state.photos=[];setTimeout(()=>auth('login','Conta excluída.'),0)},'Excluir definitivamente');},
 'logout':async()=>{clearTimeout(saveTimer);if(state.draft&&state.dirty)await saveDraft();if(!state.demo)await api('logout','POST',{});clearPrivateCache();state.demo=false;state.user=null;state.draft=null;state.photos=[];state.records=[];state.ai=null;modal.close();auth();}
};
function clearPrivateCache(){if(state.user)localStorage.removeItem('forma-draft-'+state.user.id)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.onclick||!actions[b.dataset.action])return;e.preventDefault();if(b.disabled)return;b.disabled=true;try{await actions[b.dataset.action](b)}catch(err){toast(err.message)}finally{b.disabled=false}});
window.addEventListener('online',()=>{if(state.dirty)saveDraft().catch(e=>toast(e.message))});
window.addEventListener('beforeunload',()=>{if(state.draft&&state.dirty)cacheDraft()});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_current_workout',description:'Lê o treino atual e suas séries, sem alterá-lo.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(input&&Object.keys(input).length)throw new Error('Não aceita argumentos.');return {name:state.draft?.data.name||null,completed:completed(state.draft?.data),sync:state.sync}}})}catch{}}
async function init(){if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const params=new URLSearchParams(location.search);if(params.has('token_hash')){try{const type=params.get('type');await api('exchange','POST',{token_hash:params.get('token_hash'),type});history.replaceState({},'',location.pathname);await load();if(type==='recovery')passwordReset()}catch(e){auth('login',e.message)}return}try{await load()}catch(e){auth('login',e.status===401?'':e.message)}}
function passwordReset(){formModal('Redefinir senha',field('new_password','Nova senha','','password','required minlength="10" autocomplete="new-password"'),async f=>{await api('password-reset','POST',f);toast('Senha redefinida.');});}
init();
